                pos <= (key == 4'd7) ? 3'd1 : 3'd0;
                if (wrong == 2'd2) begin
                    wrong <= 2'd0; atimer <= 5'd20;
                end else
                    wrong <= wrong + 2'd1;
            end
        end
    end
endmodule
